#!/usr/bin/env bash
# Portable, non-secret user profile.
#
# There is no GitHub account store: settings live only in the keyed Cloudflare
# KV entry (and in ~/.glide as a local cache). The key is a random 256-bit
# capability generated by `glide link`; it is shown once and stored locally in
# ~/.glide/sync.key (mode 600). No passwords, tokens or Microsoft credentials
# ever go into the profile.

GLIDE_PROFILE_FILE="${GLIDE_PROFILE_FILE:-$GLIDE_ROOT/.glide/profile.env}"
GLIDE_SYNC_URL="${GLIDE_SYNC_URL:-https://glide-profile-sync.amphibianclientlauncher.workers.dev}"
GLIDE_SYNC_KEY_FILE="${GLIDE_SYNC_KEY_FILE:-$GLIDE_HOME/sync.key}"
GLIDE_PROFILE_KEYS=(
  GLIDE_MINECRAFT_VERSION
  GLIDE_MINECRAFT_LOADER
  GLIDE_MINECRAFT_XMX
  GLIDE_RESOLUTION
  GLIDE_FPS
  GLIDE_BITRATE
  GLIDE_ENCODER
  GLIDE_DASHBOARD
  GLIDE_AUDIO
  GLIDE_AUTH_MODE
  GLIDE_OFFLINE_USERNAME
  GLIDE_MICROSOFT_CLIENT_ID
  GLIDE_MAX_RESTARTS
  GLIDE_RENDERER
)

glide_profile_allowed() {
  local needle="$1" key
  for key in "${GLIDE_PROFILE_KEYS[@]}"; do
    [ "$key" = "$needle" ] && return 0
  done
  return 1
}

glide_profile_import() {
  [ -f "$GLIDE_PROFILE_FILE" ] || return 0
  glide_ensure_dirs
  [ -f "$GLIDE_SESSION_ENV" ] || glide_write_defaults
  local tmp="$GLIDE_SESSION_ENV.import" key value next
  cp -f "$GLIDE_SESSION_ENV" "$tmp" 2>/dev/null || : >"$tmp"
  while IFS='=' read -r key value || [ -n "${key:-}" ]; do
    key="$(printf '%s' "${key:-}" | tr -d '[:space:]')"
    value="$(printf '%s' "${value:-}" | sed 's/[[:space:]]*$//')"
    [ -n "$key" ] || continue
    case "$key" in \#*) continue ;; esac
    glide_profile_allowed "$key" || continue
    [ -n "$value" ] || continue
    next="$tmp.next"
    awk -v k="$key" -v v="$value" 'BEGIN{FS=OFS="="} $1==k{print k"="v; next} {print}' \
      "$tmp" >"$next" 2>/dev/null || : >"$next"
    mv "$next" "$tmp"
    if ! grep -q "^${key}=" "$tmp" 2>/dev/null; then
      printf '%s=%s\n' "$key" "$value" >>"$tmp"
    fi
  done <"$GLIDE_PROFILE_FILE"
  mv "$tmp" "$GLIDE_SESSION_ENV"
}

glide_profile_export() {
  mkdir -p "$(dirname "$GLIDE_PROFILE_FILE")"
  local tmp="$GLIDE_PROFILE_FILE.tmp" key value
  {
    printf '# Glide profile - non-secret settings, local cache.\n'
    for key in "${GLIDE_PROFILE_KEYS[@]}"; do
      value="$(awk -F= -v k="$key" '$1==k { sub(/^[^=]*=/, ""); print; exit }' "$GLIDE_SESSION_ENV" 2>/dev/null)"
      [ -n "$value" ] && printf '%s=%s\n' "$key" "$value"
    done
  } >"$tmp"
  mv "$tmp" "$GLIDE_PROFILE_FILE"
}

glide_sync_key() {
  [ -f "$GLIDE_SYNC_KEY_FILE" ] || return 1
  local key
  key="$(tr -d '[:space:]' <"$GLIDE_SYNC_KEY_FILE" 2>/dev/null)"
  printf '%s' "$key" | grep -Eq '^[a-f0-9]{64}$' || return 1
  printf '%s' "$key"
}

glide_profile_linked() {
  glide_sync_key >/dev/null 2>&1
}

glide_sync_push() {
  local key output
  key="$(glide_sync_key)" || return 1
  output="$(GLIDE_SYNC_KEY="$key" GLIDE_SYNC_URL="$GLIDE_SYNC_URL" \
    python3 "$GLIDE_ROOT/codespace/profile_remote.py" push "$GLIDE_PROFILE_FILE" 2>&1)"
  case "$output" in
    pushed) glide_log "profile saved to the portable store" ;;
    *) glide_log "portable profile push failed: $output" ;;
  esac
  return 0
}

glide_sync_pull() {
  local key output
  key="$(glide_sync_key)" || return 2
  output="$(GLIDE_SYNC_KEY="$key" GLIDE_SYNC_URL="$GLIDE_SYNC_URL" \
    python3 "$GLIDE_ROOT/codespace/profile_remote.py" pull "$GLIDE_PROFILE_FILE" 2>&1)"
  local rc=$?
  case "$rc" in
    0)
      [ "$output" = "updated" ] && glide_log "profile restored from the portable store"
      return 0
      ;;
    3) return 2 ;;
    *)
      glide_log "portable profile pull failed: $output"
      return 1
      ;;
  esac
}

glide_profile_pull() {
  glide_profile_linked || return 0
  glide_sync_pull || true
  return 0
}

glide_profile_sync() {
  glide_profile_export
  if ! glide_profile_linked; then
    glide_log "profile saved locally; run 'glide link' to sync across accounts"
    return 0
  fi
  glide_sync_push
  return 0
}

glide_link_game() {
  declare -F glide_game_pull >/dev/null 2>&1 || return 0
  local rc
  glide_game_pull
  rc=$?
  case "$rc" in
    0) glide_log "game settings restored" ;;
    2) glide_game_push ;;
  esac
  return 0
}

# glide link [key]
# With no key: paste an existing key, or press Enter to generate one.
glide_profile_link() {
  local key="${1:-}" new=0 rc
  if [ -z "$key" ]; then
    if [ ! -t 0 ]; then
      glide_log "linking needs a terminal; run: glide link <key>"
      return 2
    fi
    read -rsp "Paste your sync key, or press Enter to create one: " key || return 2
    printf '\n'
  fi
  if [ -z "$key" ]; then
    key="$(python3 -c 'import secrets; print(secrets.token_hex(32))')"
    new=1
  fi
  key="$(printf '%s' "$key" | tr -d '[:space:]' | tr 'A-F' 'a-f')"
  if ! printf '%s' "$key" | grep -Eq '^[a-f0-9]{64}$'; then
    printf 'That is not a valid 64-character sync key.\n' >&2
    return 2
  fi
  mkdir -p "$(dirname "$GLIDE_SYNC_KEY_FILE")"
  umask 077
  printf '%s\n' "$key" >"$GLIDE_SYNC_KEY_FILE"
  chmod 600 "$GLIDE_SYNC_KEY_FILE"

  if [ "$new" = "1" ]; then
    glide_profile_sync
    glide_game_push
    printf '\nYour sync key (save it now):\n\n  %s\n\n' "$key"
    printf 'On another account/codespace: Glide: Link profile, then paste this key.\n'
    glide_log "new sync key created; current settings uploaded"
    return 0
  fi

  glide_sync_pull
  rc=$?
  if [ "$rc" -eq 0 ]; then
    glide_profile_import
    glide_load_env >/dev/null 2>&1 || true
    glide_link_game
    glide_log "linked; settings restored (restart the game if it was running)"
    return 0
  fi
  if [ "$rc" -eq 2 ]; then
    rm -f "$GLIDE_SYNC_KEY_FILE"
    printf 'No settings were found for that key. Check it and try again.\n' >&2
    return 1
  fi
  glide_log "key saved, but the portable store could not be reached"
  return 1
}

glide_profile_unlink() {
  rm -f "$GLIDE_SYNC_KEY_FILE"
  glide_log "unlinked; this codespace keeps its local settings"
}

glide_profile_show_key() {
  local key
  if key="$(glide_sync_key)"; then
    printf '%s\n' "$key"
  else
    printf 'No sync key linked. Run: glide link\n' >&2
    return 1
  fi
}
